#### JavaScript Code

Next, update your JavaScript code to render the project cards and modal popups correctly:

```javascript
// Import necessary Bootstrap components
import { Card, Modal } from 'bootstrap';

// Define the project cards
const projectCards = [
  { id: 1, name: 'Project 1', description: 'This is project 1', image: 'path/to/project1.jpg' },
  { id: 2, name: 'Project 2', description: 'This is project 2', image: 'path/to/project2.jpg' },
  // ...
  { id: 10, name: 'Project 10', description: 'This is project 10', image: 'path/to/project10.jpg' }
];

// Render the project cards
projectCards.forEach((project) => {
  const card = document.createElement('div');
  card.classList.add('col-md-3', 'mb-4'); // Use col-md-3 for a 4-column layout on medium screens and above
  card.innerHTML = `
    <div class="card h-100">
      <img src="${project.image}" class="card-img-top" alt="${project.name}">
      <div class="card-body">
        <h5 class="card-title">${project.name}</h5>
        <p class="card-text">${project.description}</p>
        <button class="btn btn-primary" data-bs-toggle="modal" data-bs-target="#project-modal-${project.id}">View Details</button>
      </div>
    </div>
  `;
  document.querySelector('#project-gallery .row').appendChild(card);
});

// Define the modal popups for project details
projectCards.forEach((project) => {
  const modal = document.createElement('div');
  modal.classList.add('modal', 'fade');
  modal.id = `project-modal-${project.id}`;
  modal.innerHTML = `
    <div class="modal-dialog">
      <div class="modal-content">
        <div class="modal-header">
          <h5 class="modal-title">${project.name}</h5>
          <button type="button" class="btn-close" data-bs-dismiss="modal" aria-label="Close"></button>
        </div>
        <div class="modal-body">
          <p>${project.description}</p>
        </div>
      </div>
    </div>
  `;
  document.getElementById('project-gallery').appendChild(modal);
});
```

